"maximum": 100000, "minimum": 0}, "folder_id": {"type": "integer", "maximum": 2147483647, "minimum": 1}, "account_id": {"type": "string", "format": "uuid"}}, "additionalProperties": false}}, {"name": "list_folders", "annotations": {"readOnlyHint": true, "idempotentHint": true, "destructiveHint": false}, "description": "Read an account's mirrored Telegram folders and their order; never modifies Telegram.", "inputSchema": {"type": "object", "required": ["account_id"], "properties": {"account_id": {"type": "string", "format": "uuid"}}, "additionalProperties": false}}, {"name": "list_audit_events", "annotations": {"readOnlyHint": true, "idempotentHint": true, "destructiveHint": false}, "description": "Read observed login, connection, edit, deletion and removal events. Never exposes login credentials.", "inputSchema": {"type": "object", "properties": {"limit": {"type": "integer", "maximum": 200, "minimum": 1}, "before": {"type": "string", "pattern": "^[0-9]{1,19}$"}, "chat_id": {"type": "string", "pattern": "^-?[0-9]+$"}, "account_id": {"type": "string", "format": "uuid"}}, "additionalProperties": false}}, {"name": "get_deleted_messages", "annotations": {"readOnlyHint": true, "idempotentHint": true, "destructiveHint": false}, "description": "Read deletion markers and last captured text. Messages not captured before deletion cannot be recovered.", "inputSchema": {"type": "object", "properties": {"limit": {"type": "integer", "maximum": 200, "minimum": 1}, "offset": {"type": "integer", "maximum": 100000, "minimum": 0}, "chat_id": {"type": "string", "pattern": "^-?[0-9]+$"}, "account_id": {"type": "string", "format": "uuid"}}, "additionalProperties": false}}, {"name": "get_capabilities", "annotations": {"readOnlyHint": true, "idempotentHint": true, "destructiveHint": false}, "description": "Inspect caller scopes and supported and unsupported workspace operations.", "inputSchema": {"type": "object", "properties": {}, "additionalProperties": false}}], "server": {"name": "open-